using LUMAR_ERP_API_V2.Data;using LUMAR_ERP_API_V2.DTOs.Purchasing;using Microsoft.Data.SqlClient;namespace LUMAR_ERP_API_V2.Repositories;
public sealed class PurchasingRepository(ReadOnlySqlConnectionFactory connections):IPurchasingRepository{
public Task<IReadOnlyList<PurchaseOrderListDto>> GetOrdersAsync(CancellationToken c)=>Q("SELECT PurchaseOrderId,PurchaseOrderNumber,SupplierId,OrderDate,ExpectedDeliveryDate,Status,TotalAmount FROM dbo.PurchaseOrders ORDER BY OrderDate DESC,PurchaseOrderId DESC",null,r=>new PurchaseOrderListDto(r.GetInt32(0),r.GetString(1),r.GetInt32(2),r.GetDateTime(3),r.NullableDateTime("ExpectedDeliveryDate"),r.GetString(5),r.GetDecimal(6)),c);public async Task<PurchaseOrderDetailsDto?> GetOrderAsync(int i,CancellationToken c)=>(await Q("SELECT PurchaseOrderId,PurchaseOrderNumber,SupplierId,OrderDate,ExpectedDeliveryDate,Status,TotalAmount,CreatedAt FROM dbo.PurchaseOrders WHERE PurchaseOrderId=@id",i,r=>new PurchaseOrderDetailsDto(r.GetInt32(0),r.GetString(1),r.GetInt32(2),r.GetDateTime(3),r.NullableDateTime("ExpectedDeliveryDate"),r.GetString(5),r.GetDecimal(6),r.GetDateTime(7)),c)).FirstOrDefault();public Task<IReadOnlyList<PurchaseOrderItemDto>> GetOrderItemsAsync(int i,CancellationToken c)=>Q("SELECT PurchaseOrderItemId,PurchaseOrderId,ItemName,Quantity,UnitCost,LineTotal FROM dbo.PurchaseOrderItems WHERE PurchaseOrderId=@id ORDER BY PurchaseOrderItemId",i,r=>new PurchaseOrderItemDto(r.GetInt32(0),r.GetInt32(1),r.GetString(2),r.GetDecimal(3),r.GetDecimal(4),r.GetDecimal(5)),c);public Task<IReadOnlyList<GoodsReceiptDto>> GetOrderReceiptsAsync(int i,CancellationToken c)=>Q("SELECT GoodsReceiptId,SupplierId,PurchaseOrderId,ReceiptNumber,ReceiptDate,Notes,CreatedAt FROM dbo.GoodsReceipts WHERE PurchaseOrderId=@id ORDER BY ReceiptDate DESC,GoodsReceiptId DESC",i,Receipt,c);public Task<IReadOnlyList<GoodsReceiptDto>> GetReceiptsAsync(CancellationToken c)=>Q("SELECT GoodsReceiptId,SupplierId,PurchaseOrderId,ReceiptNumber,ReceiptDate,Notes,CreatedAt FROM dbo.GoodsReceipts ORDER BY ReceiptDate DESC,GoodsReceiptId DESC",null,Receipt,c);public async Task<GoodsReceiptDto?> GetReceiptAsync(int i,CancellationToken c)=>(await Q("SELECT GoodsReceiptId,SupplierId,PurchaseOrderId,ReceiptNumber,ReceiptDate,Notes,CreatedAt FROM dbo.GoodsReceipts WHERE GoodsReceiptId=@id",i,Receipt,c)).FirstOrDefault();public Task<IReadOnlyList<GoodsReceiptItemDto>> GetReceiptItemsAsync(int i,CancellationToken c)=>Q("SELECT GoodsReceiptItemId,GoodsReceiptId,ItemName,ReceivedQuantity,UnitCost,LineTotal FROM dbo.GoodsReceiptItems WHERE GoodsReceiptId=@id ORDER BY GoodsReceiptItemId",i,r=>new GoodsReceiptItemDto(r.GetInt32(0),r.GetInt32(1),r.GetString(2),r.GetDecimal(3),r.GetDecimal(4),r.GetDecimal(5)),c);public Task<IReadOnlyList<PurchasingInvoiceDto>> GetInvoicesAsync(CancellationToken c)=>Q("SELECT SupplierInvoiceId,SupplierId,PurchaseOrderId,InvoiceNumber,InvoiceDate,DueDate,TotalAmount,AmountPaid,Status,Notes,CreatedAt FROM dbo.SupplierInvoices ORDER BY InvoiceDate DESC,SupplierInvoiceId DESC",null,Invoice,c);public async Task<PurchasingInvoiceDto?> GetInvoiceAsync(int i,CancellationToken c)=>(await Q("SELECT SupplierInvoiceId,SupplierId,PurchaseOrderId,InvoiceNumber,InvoiceDate,DueDate,TotalAmount,AmountPaid,Status,Notes,CreatedAt FROM dbo.SupplierInvoices WHERE SupplierInvoiceId=@id",i,Invoice,c)).FirstOrDefault();public Task<IReadOnlyList<PurchasingPaymentDto>> GetPaymentsAsync(CancellationToken c)=>Q("SELECT SupplierPaymentId,SupplierId,PaymentNumber,PaymentDate,Amount,PaymentMethod,ReferenceNumber,Notes,CreatedAt,JournalEntryId FROM dbo.SupplierPayments ORDER BY PaymentDate DESC,SupplierPaymentId DESC",null,Payment,c);public async Task<PurchasingPaymentDto?> GetPaymentAsync(int i,CancellationToken c)=>(await Q("SELECT SupplierPaymentId,SupplierId,PaymentNumber,PaymentDate,Amount,PaymentMethod,ReferenceNumber,Notes,CreatedAt,JournalEntryId FROM dbo.SupplierPayments WHERE SupplierPaymentId=@id",i,Payment,c)).FirstOrDefault();public Task<IReadOnlyList<PurchasingPaymentAllocationDto>> GetAllocationsAsync(int i,CancellationToken c)=>Q("SELECT SupplierPaymentAllocationId,SupplierPaymentId,SupplierInvoiceId,AllocatedAmount,AllocationDate,Notes,CreatedAt FROM dbo.SupplierPaymentAllocations WHERE SupplierPaymentId=@id ORDER BY AllocationDate DESC,SupplierPaymentAllocationId DESC",i,r=>new PurchasingPaymentAllocationDto(r.GetInt32(0),r.GetInt32(1),r.GetInt32(2),r.GetDecimal(3),r.GetDateTime(4),r.NullableString("Notes"),r.GetDateTime(6)),c);private static GoodsReceiptDto Receipt(SqlDataReader r)=>new(r.GetInt32(0),r.GetInt32(1),r.GetInt32(2),r.GetString(3),r.GetDateTime(4),r.NullableString("Notes"),r.GetDateTime(6));private static PurchasingInvoiceDto Invoice(SqlDataReader r)=>new(r.GetInt32(0),r.GetInt32(1),r.GetInt32(2),r.GetString(3),r.GetDateTime(4),r.GetDateTime(5),r.GetDecimal(6),r.GetDecimal(7),r.GetString(8),r.NullableString("Notes"),r.GetDateTime(10));private static PurchasingPaymentDto Payment(SqlDataReader r)=>new(r.GetInt32(0),r.GetInt32(1),r.GetString(2),r.GetDateTime(3),r.GetDecimal(4),r.NullableString("PaymentMethod"),r.NullableString("ReferenceNumber"),r.NullableString("Notes"),r.GetDateTime(8),r.NullableInt32("JournalEntryId"));private async Task<IReadOnlyList<T>> Q<T>(string sql,int? id,Func<SqlDataReader,T> map,CancellationToken ct){await using var c=connections.Create();await c.OpenAsync(ct);await using var cmd=new SqlCommand(sql,c);if(id.HasValue)cmd.Parameters.AddWithValue("@id",id.Value);await using var r=await cmd.ExecuteReaderAsync(ct);var x=new List<T>();while(await r.ReadAsync(ct))x.Add(map(r));return x;}}